exec('import csv,os,math,yfinance as yf\ncash_file="portfolio_cash.csv"; portfolio_file="virtual_portfolio.csv"; decision_file="intraday_decisions.csv"\ncash_rows=list(csv.DictReader(open(cash_file,encoding="utf-8"))); cash=cash_rows[0]; available=float(cash["available_cash_eur"]); positions=list(csv.DictReader(open(portfolio_file,encoding="utf-8"))) if os.path.exists(portfolio_file) else []; decisions=list(csv.DictReader(open(decision_file,encoding="utf-8"))) if os.path.exists(decision_file) else []; signals=list(csv.DictReader(open("signals_history.csv",encoding="utf-8"))) if os.path.exists("signals_history.csv") else []; score_map={(r["ticker"],r["date"]):int(r["score"]) for r in signals}; open_count=sum(1 for p in positions if p.get("status")=="OPEN"); used={(p["ticker"],p["signal_date"]) for p in positions}; candidates=[r for r in decisions if r.get("next_state")=="POSITION A OUVRIR" and r.get("decision") in ("ACHAT CONFIRME","ACHAT REACTIVE") and (r["ticker"],r["signal_date"]) not in used]; candidates.sort(key=lambda r:(score_map.get((r["ticker"],r["signal_date"]),0),float(r.get("decision_volume") or 0)),reverse=True)\nfx_data=yf.download("EURUSD=X",period="1mo",progress=False,auto_adjust=True)["Close"].squeeze().dropna()\ndef fx_at(date):\n q=fx_data[fx_data.index.strftime("%Y-%m-%d")<=date]; return float(q.iloc[-1]) if len(q) else float(fx_data.iloc[-1])\ndef euro_fee(gross): return 1.0 if gross<=1000 else 2.55\nfor r in candidates:\n if open_count>=3: print("REFUSE",r["ticker"],"| maximum 3 positions"); continue\n t=r["ticker"]; price=float(r["decision_close"]); currency="EUR" if t.endswith((".PA",".AS")) else "USD"; rate=1.0 if currency=="EUR" else fx_at(r["session_date"]); budget=min(1000.0,available); qty=0\n if currency=="EUR":\n  qty=math.floor(max(0,budget-1.0)/price)\n  if qty==0 and 1000<price<2000 and available>=price+2.55: qty=1\n  gross_local=qty*price; gross_eur=gross_local; buy_fee=euro_fee(gross_eur) if qty else 0\n else:\n  qty=math.floor(max(0,budget-10.5)*rate/price); gross_local=qty*price; gross_eur=gross_local/rate; buy_fee=10.5 if qty else 0\n total_cost=gross_eur+buy_fee\n if qty<1 or total_cost>available+0.0001: print("NON EXECUTABLE",t,"| cash",round(available,2),"EUR | prix",price,currency); continue\n sell_fee=10.5 if currency=="USD" else euro_fee(total_cost*1.03); target_net=total_cost*1.03; stop_net=total_cost*0.98; target_local=((target_net+sell_fee)/qty)*(rate if currency=="USD" else 1); stop_local=((stop_net+sell_fee)/qty)*(rate if currency=="USD" else 1); available-=total_cost; positions.append({"ticker":t,"signal_date":r["signal_date"],"decision":r["decision"],"decision_time":r["decision_time"],"entry_date":r["session_date"],"entry_price":round(price,4),"currency":currency,"eurusd_entry":round(rate,6),"quantity":qty,"gross_buy_value_local":round(gross_local,2),"gross_buy_value_eur":round(gross_eur,2),"buy_fee_eur":round(buy_fee,2),"total_buy_cost_eur":round(total_cost,2),"target_price":round(target_local,4),"stop_price":round(stop_local,4),"status":"OPEN","last_price":round(price,4),"market_value_eur":round(gross_eur,2),"unrealized_pnl_eur":round(-buy_fee,2),"exit_date":"","exit_price":"","gross_sell_value_local":"","gross_sell_value_eur":"","sell_fee_eur":"","net_sell_proceeds_eur":"","realized_pnl_eur":"","exit_reason":""}); open_count+=1; print("ACHAT",t,"|",qty,"action(s) | cout total",round(total_cost,2),"EUR | cash restant",round(available,2),"EUR")\nmarket_value=sum(float(p.get("market_value_eur") or 0) for p in positions if p.get("status")=="OPEN"); invested=sum(float(p.get("total_buy_cost_eur") or 0) for p in positions if p.get("status")=="OPEN"); realized=sum(float(p.get("realized_pnl_eur") or 0) for p in positions if p.get("status")=="CLOSED"); unrealized=sum(float(p.get("unrealized_pnl_eur") or 0) for p in positions if p.get("status")=="OPEN"); fees=sum(float(p.get("buy_fee_eur") or 0)+float(p.get("sell_fee_eur") or 0) for p in positions); equity=available+market_value\nfields=["ticker","signal_date","decision","decision_time","entry_date","entry_price","currency","eurusd_entry","quantity","gross_buy_value_local","gross_buy_value_eur","buy_fee_eur","total_buy_cost_eur","target_price","stop_price","status","last_price","market_value_eur","unrealized_pnl_eur","exit_date","exit_price","gross_sell_value_local","gross_sell_value_eur","sell_fee_eur","net_sell_proceeds_eur","realized_pnl_eur","exit_reason"]\nwith open(portfolio_file,"w",newline="",encoding="utf-8") as q:\n w=csv.DictWriter(q,fieldnames=fields,extrasaction="ignore"); w.writeheader(); w.writerows(positions)\ncash_out={"initial_capital_eur":3000,"available_cash_eur":round(available,2),"invested_cost_eur":round(invested,2),"market_value_eur":round(market_value,2),"realized_pnl_eur":round(realized,2),"unrealized_pnl_eur":round(unrealized,2),"fees_paid_eur":round(fees,2),"total_equity_eur":round(equity,2)}\nwith open(cash_file,"w",newline="",encoding="utf-8") as q:\n w=csv.DictWriter(q,fieldnames=list(cash_out)); w.writeheader(); w.writerow(cash_out)\nprint("Capital mis a jour | cash",round(available,2),"EUR | equity",round(equity,2),"EUR")')
